package com.example.cvd;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
public class StatisticsMigrationCheck {
 static final ObjectMapper mapper=new ObjectMapper();static final String ID=Equipment.FIRST;
 static void check(boolean b,String reason){if(!b)throw new AssertionError(reason);}
 static ObjectNode closed(int seq,Instant at){var e=mapper.createObjectNode();e.put("kind","wafer-closed");e.put("equipmentId",ID);e.put("waferId","w"+seq);e.put("sourceTime",at.toString());var p=e.putObject("payload");p.put("version",1);p.put("purpose","production");p.put("result","success");p.put("returnedAt",at.toString());p.put("closedAt",at.toString());p.put("era","test");p.put("closureSequence",seq);return e;}
 static ObjectNode sample(Instant at,long count){var e=mapper.createObjectNode();e.put("equipmentId",ID);e.put("quality","good");e.put("sourceEpoch","epoch");e.put("sequence",1);e.put("sourceTime",at.plusSeconds(1).toString());var p=e.putObject("payload");var u=p.putObject("utilization");u.put("version",1);u.put("intervalStart",at.toString());u.put("intervalEnd",at.plusSeconds(1).toString());var pm=u.putObject("pm");for(int i=1;i<=4;i++)pm.put("PM"+i,false);var s=p.putObject("statistics");s.put("version",1);s.put("state","idle");s.put("flags",0);s.put("era","test");s.put("closureCount",count);return e;}
 public static void main(String[] args){
  var pg=new JdbcTemplate(new DriverManagerDataSource("jdbc:postgresql://postgres:5432/statistics_check","cvd","cvd-local"));var db=new DataStore(pg,mapper,"jdbc:postgresql://timescaledb:5432/statistics_check","cvd","cvd-local");db.migrate();var store=new StatisticsStore(db);store.migrate();store.migrate();var util=new UtilizationStore(db);util.migrate();var api=new StatisticsApi(store,new UtilizationApi(util));
  Instant end=Instant.now().truncatedTo(ChronoUnit.MINUTES).minusSeconds(60),at=end.minusSeconds(60);
  var two=closed(2,at.plusSeconds(2));store.closed(two);store.closed(two);check(store.receipts().get(ID+"/test")==0,"out of order receipt complete");store.closed(closed(1,at.plusSeconds(1)));check(store.receipts().get(ID+"/test")==2,"receipt gap unresolved");check(pg.queryForObject("SELECT count(*) FROM statistics_closures",Integer.class)==2,"duplicate closures");check(store.closures(at,at.plusSeconds(2)).stream().mapToLong(r->((Number)r.get("amount")).longValue()).sum()==1,"end boundary included");
  for(int n=0;n<60;n++){var e=sample(at.plusSeconds(n),2);store.ingest(e);store.ingest(e);}
  check(db.ts.queryForObject("SELECT count(*) FROM statistics_second",Integer.class)==60,"duplicate seconds");var row=api.report("24h",end);var first=((List<Map<String,Object>>)row.get("equipment")).getFirst();check(((Map<String,Long>)first.get("states")).get("idle")==60,"minute totals");check(((Number)((Map<?,?>)first.get("production")).get("knownSeconds")).longValue()==60,"coverage does not match receipt");
  var conflict=sample(at,2);((ObjectNode)conflict.path("payload").path("statistics")).put("state","fault");store.ingest(conflict);store.ingest(sample(at,2));check(db.ts.queryForObject("SELECT sum(samples) FROM statistics_minute WHERE state='unknown'",Long.class)==1,"conflict not sticky");
  var backfill=new StatisticsBackfill(db,store);backfill.migrate();Instant legacy=at.minusSeconds(20);var process=mapper.createObjectNode();process.putObject("payload").put("complete",true);var ret=mapper.createObjectNode();ret.put("sourceTime",legacy.toString());ret.putObject("payload").put("to","LP1");
  pg.update("INSERT INTO history(id,time,kind,body,wafer_id,lot_id,equipment_id) VALUES('p',?::timestamptz,'process-result',?::jsonb,'legacy','lot',?),('r',?::timestamptz,'movement-complete',?::jsonb,'legacy','lot',?)",legacy.minusSeconds(1).toString(),process.toString(),ID,legacy.toString(),ret.toString(),ID);
  var input=new HashMap<String,Object>();input.put("equipment_id",ID);input.put("lp","LP1");input.put("purpose","production");input.put("lot_id","lot");input.put("wafer","{\"id\":\"legacy\",\"result\":\"success\",\"attempts\":1}");input.put("incidents","{}");var e=backfill.reconstruct(input);check(e!=null&&StatisticsStore.closureValid(e),"reliable legacy not recovered");store.project(e);store.project(e);check(pg.queryForObject("SELECT count(*) FROM statistics_closures WHERE wafer_id='legacy'",Integer.class)==1,"backfill duplicate");input.put("wafer","{\"id\":\"missing\",\"result\":\"success\",\"attempts\":1}");check(backfill.reconstruct(input)==null,"fabricated legacy closure");
  // 30 days, ten machines: minute facts are a bounded input, never transmit raw seconds.
  if(args.length==0){
  db.ts.update("INSERT INTO statistics_minute SELECT t,id,'paused',65536,'bench',60,0,60 FROM generate_series(?::timestamptz-interval '30 days',?::timestamptz-interval '1 minute',interval '1 minute') t CROSS JOIN unnest(?::text[]) id ON CONFLICT DO NOTHING",end.toString(),end.toString(),"{"+String.join(",",Equipment.IDS)+"}");
  // Avoid overlapping the live fixture's minute in the benchmark data.
  db.ts.update("DELETE FROM statistics_minute WHERE equipment_id=? AND time=?::timestamptz AND era='bench'",ID,at.toString());
  long began=System.nanoTime();var report=api.report("30d",end);long ms=(System.nanoTime()-began)/1000000;var tools=(List<Map<String,Object>>)report.get("equipment");for(var tool:tools){check(((Collection<?>)tool.get("timeline")).size()<=2017,"unbounded timeline");check(((Map<String,Long>)tool.get("states")).values().stream().mapToLong(Long::longValue).sum()==30L*86400,"incorrect state sum");}System.out.println("PASS migration/replay/order/conflict/boundaries/legacy; 30-day ten-machine report ms="+ms+" jsonBytes="+db.mapper.valueToTree(report).toString().length());
  }
  // Tombstones retain deduplication after detailed payload expiration.
  pg.update("UPDATE statistics_closures SET body='{}' WHERE wafer_id='w1'");store.closed(closed(1,at.plusSeconds(1)));check(pg.queryForObject("SELECT count(*) FROM statistics_closures WHERE wafer_id='w1'",Integer.class)==1,"expired replay recounted");
  var mismatch=closed(1,at.plusSeconds(1));mismatch.put("waferId","contradictory");store.closed(mismatch);check(store.receipts().get(ID+"/test")==-1,"sequence conflict not poisoned");check(pg.queryForObject("SELECT count(*) FROM statistics_closures WHERE wafer_id IN ('w1','contradictory') AND conflict",Integer.class)==2,"conflicting sequence counted as known");
  var nativeRow=new HashMap<String,Object>();nativeRow.put("equipment_id",Equipment.IDS.get(1));nativeRow.put("era","native");nativeRow.put("lot_id","native-lot");nativeRow.put("incidents","{}");nativeRow.put("wafer","{\"id\":\"native-wafer\",\"purpose\":\"dummy\",\"result\":\"success\",\"closureSequence\":1,\"closedAt\":\""+at+"\",\"lastReturnAt\":\""+at+"\"}");var nativeEvent=backfill.nativeEvidence(nativeRow);check(nativeEvent!=null&&StatisticsStore.closureValid(nativeEvent),"native repair evidence invalid");store.closed(nativeEvent);check(store.receipts().get(Equipment.IDS.get(1)+"/native")==1,"native sequence gap not repaired");// A legacy projection may already exist before the native receipt arrives.
  pg.update("DELETE FROM statistics_receipts WHERE era='native'");pg.update("DELETE FROM statistics_eras WHERE era='native'");var snap=mapper.createObjectNode();snap.put("statisticsEra","native");snap.putObject("incidents");var lot=snap.putArray("lots").addObject();lot.put("id","native-lot");lot.put("lp","LP1");lot.put("purpose","dummy");lot.put("phase","complete");var nw=(ObjectNode)db.parse((String)nativeRow.get("wafer"));nw.put("location","LP1");lot.putArray("wafers").add(nw);pg.update("INSERT INTO equipment_snapshot(id,version,body) VALUES(?,1,?::jsonb)",Equipment.IDS.get(1),snap.toString());backfill.run();check(store.receipts().get(Equipment.IDS.get(1)+"/native")==1,"existing projection blocked missing receipt repair");
  System.out.println("PASS tombstone replay, contradictory sequence exclusion, native Dummy repair including existing projection, machine isolation");
  var active=closed(99,Instant.now().minus(Duration.ofDays(31)));active.put("lotId","parked-production");store.project(active);var activeSnap=mapper.createObjectNode();var parked=activeSnap.putArray("lots").addObject();parked.put("id","parked-production");parked.put("purpose","production");parked.put("parked",true);parked.put("phase","paused");pg.update("INSERT INTO equipment_snapshot(id,version,body) VALUES(?,1,?::jsonb)",ID,activeSnap.toString());store.cleanup();check(pg.queryForObject("SELECT body<>'{}'::jsonb FROM statistics_closures WHERE equipment_id=? AND wafer_id='w99'",Boolean.class,ID),"parked active FOUP evidence removed");parked.put("phase","complete");pg.update("UPDATE equipment_snapshot SET body=?::jsonb WHERE id=?",activeSnap.toString(),ID);store.cleanup();check(pg.queryForObject("SELECT body='{}'::jsonb FROM statistics_closures WHERE equipment_id=? AND wafer_id='w99'",Boolean.class,ID),"expired completed evidence not trimmed");store.project(active);check(pg.queryForObject("SELECT count(*) FROM statistics_closures WHERE equipment_id=? AND wafer_id='w99'",Integer.class,ID)==1,"old closure replay duplicated after cleanup");System.out.println("PASS active parked FOUP protection and completed evidence cleanup");
  ((com.zaxxer.hikari.HikariDataSource)db.ts.getDataSource()).close();
 }
}
